    return {'type':'state','phase':state['phase'],'question_no':state['question_no'],'question':state['question'],'deadline':state['deadline'],'player_count':len(state['players']),'spectator_count':len(state['spectators']),'winner':state['winner'],'config':state['config'],'contestants':[{'name':r['name'],'bot':bool(r.get('bot')),'look':r.get('look','真人玩家'),'persona':r.get('persona','真人'),'intro':r.get('intro',''),'winline':r.get('winline',''),'outline':r.get('outline','')} for r in state['players'].values()]}

