def reset_match():
    old_event=state.get('single_answer_event')
    state['run_id']=state.get('run_id',0)+1
    state.update(phase='lobby',question_no=0,question=None,deadline=0,players={},spectators={},answers={},winner=None,single_answer_event=None)
    state['single_mode']=False
    state['bots']={}
    if old_event: old_event.set()

@app.websocket('/ws')
async def ws_endpoint(ws:WebSocket):
    await ws.accept(); meta={'name':'訪客','role':'spectator'}; clients[ws]=meta
    await ws.send_text(json.dumps(public_state(),ensure_ascii=False))
    try:
        while True:
            d=json.loads(await ws.receive_text()); typ=d.get('type')
            if typ=='join':
                name=(d.get('name') or '匿名')[:16]; role=d.get('role','spectator')
                if state['phase']!='lobby' and role=='player': role='spectator'
                if role=='player' and len(state['players'])>=state['config']['max_players']: role='spectator'
                meta.update(name=name,role=role); pid=str(id(ws)); meta['pid']=pid
                (state['players'] if role=='player' else state['spectators'])[pid]={'name':name,'alive':role=='player','correct':0,'answered':0}
                await broadcast(public_state())
                await ws.send_text(json.dumps({'type':'joined','role':role,'pid':pid},ensure_ascii=False))
            elif typ=='single_start' and meta.get('pid'):
                pid=meta['pid']
                if state['phase']=='finished':
                    reset_match()
                if state['phase']!='lobby':
                    await ws.send_text(json.dumps({'type':'error','text':'目前已有比賽進行中'},ensure_ascii=False)); continue
                total=max(4,min(16,int(d.get('total',8))))
                if total not in (4,8,12,16): total=8
                human=state['players'].get(pid) or state['spectators'].get(pid) or {'name':meta.get('name','玩家'),'alive':True,'correct':0,'answered':0}
                state['run_id']=state.get('run_id',0)+1
                used.clear(); state['players']={pid:{**human,'alive':True,'correct':0,'answered':0}}; state['spectators']={}; state['bots']={}; state['single_mode']=True; state['single_answer_event']=asyncio.Event(); state['question_no']=0; state['winner']=None
                meta['role']='player'
                for i,bot in enumerate(random.sample(BOT_CATALOG,total-1),1):
                    name,look,skill=bot['name'],bot['look'],bot['skill']
                    bid=f'bot-{i}-{random.randint(1000,9999)}'
                    state['players'][bid]={'name':name,'alive':True,'correct':0,'answered':0,'bot':True,'look':look,'skill':max(.45,min(.97,skill+random.uniform(-.05,.05))),'persona':bot['persona'],'intro':random.choice(bot['intro']),'winline':random.choice(bot['win']),'outline':random.choice(bot['out'])}
                    state['bots'][bid]=True
                state['config']['min_players']=2; state['config']['max_players']=16
                await ws.send_text(json.dumps({'type':'joined','role':'player','pid':pid},ensure_ascii=False))
                await broadcast(public_state())
                asyncio.create_task(run_game(60))
            elif typ=='answer' and meta.get('pid'):
                pid=meta['pid']; idx=int(d.get('idx',-1))
                if state['phase']=='question' and time.time()<state['deadline'] and pid not in state['answers'] and 0 <= idx < len((state.get('question') or {}).get('opts',[])):
                    state['answers'][pid]=idx
                    rec=state['players'].get(pid) or state['spectators'].get(pid)
                    if rec: rec['answered']+=1
                    if state.get('single_mode') and rec and not rec.get('bot') and state.get('single_answer_event'):
                        state['single_answer_event'].set()
            elif typ=='exit_single' and meta.get('pid'):
                if state.get('single_mode'):
                    reset_match()
                    await broadcast(public_state())
                await ws.send_text(json.dumps({'type':'returned_home'},ensure_ascii=False))
            elif typ=='admin_config' and d.get('admin')=='fishboss' and state['phase']=='lobby':
                state['config']['seconds']=max(5,min(120,int(d.get('seconds',20))))
                state['config']['min_players']=max(1,min(100,int(d.get('min_players',2))))
                state['config']['max_players']=max(state['config']['min_players'],min(100,int(d.get('max_players',100))))
                state['config']['choices']=3 if int(d.get('choices',4))==3 else 4
                await broadcast(public_state())
            elif typ=='start' and d.get('admin')=='fishboss':
                state['single_mode']=False
                state['config']['seconds']=max(5,min(120,int(d.get('seconds',20)))); asyncio.create_task(run_game(state['config']['seconds']))
            elif typ=='giveup' and meta.get('pid') in state['players']:
                pid=meta['pid']; rec=state['players'].pop(pid); rec['alive']=False; state['spectators'][pid]=rec; meta['role']='spectator'; await ws.send_text(json.dumps({'type':'role_changed','role':'spectator','reason':'giveup'},ensure_ascii=False)); await broadcast(public_state())
    except WebSocketDisconnect:
        m=clients.pop(ws,None)
        if m and m.get('pid'):
            pid=m['pid']
            was_single_human=state.get('single_mode') and (pid in state['players'] or pid in state['spectators'])
            state['spectators'].pop(pid,None)
            if pid in state['players'] and not state['players'][pid].get('bot'):
                state['players'].pop(pid,None)
                if state.get('single_mode'):
                    state['phase']='finished'; state['winner']=None; state['question']=None; state['deadline']=0
                if state.get('single_answer_event'): state['single_answer_event'].set()
            if was_single_human:
                reset_match()
        try: await broadcast(public_state())
        except: pass

async def run_game(seconds=20):
    if state['phase']!='lobby': return
    if len(state['players']) < state['config']['min_players']:
        await broadcast({'type':'cancelled','text':'未達最低參加人數，本場取消'})
        return
    run_id=state.get('run_id',0)
    state['phase']='question'; state['winner']=None
    while len(state['players'])>1:
        if run_id!=state.get('run_id') or state['phase']=='lobby': return
        if state.get('single_mode') and not any(not r.get('bot') for r in state['players'].values()):
            state['phase']='finished'; state['winner']=None; state['question']=None; state['deadline']=0
            await broadcast(public_state()); return
        # Avoid repeats within a match and strongly avoid recently seen questions across matches.
        available=[i for i in range(len(QUESTIONS)) if i not in used and i not in recent_global]
        if not available:
            available=[i for i in range(len(QUESTIONS)) if i not in used]
        if not available:
            used.clear(); available=list(range(len(QUESTIONS)))
        # Avoid serving the same category too many times in a row.
        recent_cats=[QUESTIONS[i]['cat'] for i in used[-2:] if 0<=i<len(QUESTIONS)]
        diverse=[i for i in available if not (len(recent_cats)==2 and recent_cats[0]==recent_cats[1]==QUESTIONS[i]['cat'])]
        qi=random.choice(diverse or available); used.append(qi); recent_global.append(qi)
        if len(recent_global)>80: del recent_global[:-80]
        q=QUESTIONS[qi]
        correct_text=q['opts'][q['a']]; wrong=[x for i,x in enumerate(q['opts']) if i!=q['a']]
        shown=[correct_text]+random.sample(wrong,state['config']['choices']-1); random.shuffle(shown); correct_idx=shown.index(correct_text)
        state['question_no']+=1; state['answers']={}; state['deadline']=time.time()+seconds
        state['question']={'cat':q['cat'],'q':q['q'],'opts':shown}
        await broadcast(public_state())
        # Computer contestants answer locally; no AI/API cost.
        if state.get('single_mode'):
            state['single_answer_event']=asyncio.Event()
            round_no=state['question_no']
            difficulty=random.uniform(-.07,.07)+max(0,(round_no-8)*.012)
            for bid,rec in list(state['players'].items()):
                if not rec.get('bot'): continue
                chance=max(.42,min(.97,rec.get('skill',.75)-difficulty+random.uniform(-.045,.045)))
                state['answers'][bid]=correct_idx if random.random()<chance else random.choice([i for i in range(len(shown)) if i!=correct_idx])
                rec['answered']+=1
            try:
                await asyncio.wait_for(state['single_answer_event'].wait(),timeout=seconds)
                await broadcast({'type':'judging','seconds':3})
                await asyncio.sleep(3)
            except asyncio.TimeoutError:
                pass
        else:
            await asyncio.sleep(seconds)
        if run_id!=state.get('run_id') or state['phase']=='lobby': return
        # score spectators
        for pid,rec in list(state['spectators'].items()):
            if pid in state['answers'] and state['answers'][pid]==correct_idx: rec['correct']+=1
        # Record whether the human player answered correctly before any role/elimination changes.
        human_correct=False
        if state.get('single_mode'):
            for hpid,hrec in state['players'].items():
                if not hrec.get('bot'):
                    human_correct=(state['answers'].get(hpid,None)==correct_idx)
                    break
        # eliminate wrong/no-answer players
        eliminated=[]
        for pid,rec in list(state['players'].items()):
            ans=state['answers'].get(pid,None); rec['answered']+=0
            if ans==correct_idx: rec['correct']+=1
            else: eliminated.append(pid)
        # Single-player pacing: keep the contest tense instead of wiping out bots in 3–4 questions.
        if state.get('single_mode') and len(state['players'])>2:
            round_no=state['question_no']
            human_wrong=[pid for pid in eliminated if not state['players'].get(pid,{}).get('bot')]
            bot_wrong=[pid for pid in eliminated if state['players'].get(pid,{}).get('bot')]
            max_bot_out=0 if round_no<=2 else (1 if round_no<=7 else (2 if round_no<=12 else max(1,len(state['players'])-1)))
            if len(bot_wrong)>max_bot_out:
                random.shuffle(bot_wrong)
                eliminated=human_wrong+bot_wrong[:max_bot_out]
            # If the human is still correct, keep one strongest rival alive through the opening rounds.
            # This prevents a 4-player match from ending after only a handful of easy questions.
            if round_no < 10 and not human_wrong:
                surviving_bots=[pid for pid,rec in state['players'].items() if rec.get('bot') and pid not in eliminated]
                if not surviving_bots:
                    doomed_bots=[pid for pid in eliminated if state['players'].get(pid,{}).get('bot')]
                    if doomed_bots:
                        ace=max(doomed_bots,key=lambda pid:state['players'][pid].get('skill',0))
                        eliminated.remove(ace)
        # if everyone would be eliminated, nobody is eliminated; continue to avoid zero-winner tie
        if len(eliminated)==len(state['players']) and len(state['players'])>1:
            await broadcast({'type':'round','result':'all_wrong','correct':correct_idx,'correct_text':shown[correct_idx],'explanation':question_explanation(q),'category':q['cat'],'human_correct':human_correct,'eliminated_names':[],'remaining_names':[r['name'] for r in state['players'].values()],'remaining_count':len(state['players'])})
            await asyncio.sleep(12)
            if run_id!=state.get('run_id') or state['phase']=='lobby': return
        else:
            bot_reactions=[]
            for pid,rec in list(state['players'].items()):
                if rec.get('bot'):
                    if pid in eliminated and rec.get('outline'):
                        bot_reactions.append(rec['name']+'：「'+rec['outline']+'」')
                    elif pid not in eliminated and state['answers'].get(pid)==correct_idx and rec.get('winline') and random.random()<0.35:
                        bot_reactions.append(rec['name']+'：「'+rec['winline']+'」')
            random.shuffle(bot_reactions); bot_reactions=bot_reactions[:2]
            eliminated_humans=[]
            for pid in eliminated:
                rec=state['players'].pop(pid); rec['alive']=False; state['spectators'][pid]=rec
                if not rec.get('bot'): eliminated_humans.append(pid)
            await broadcast({'type':'round','result':'resolved','correct':correct_idx,'correct_text':shown[correct_idx],'explanation':question_explanation(q),'category':q['cat'],'human_correct':human_correct,'eliminated':eliminated,'eliminated_names':[state['spectators'][x]['name'] for x in eliminated if x in state['spectators']],'remaining_names':[r['name'] for r in state['players'].values()],'remaining_count':len(state['players']),'round_no':state['question_no'],'bot_reactions':bot_reactions})
            await asyncio.sleep(7)
            if run_id!=state.get('run_id') or state['phase']=='lobby': return
            for pid in eliminated_humans:
                for w,m in clients.items():
                    if m.get('pid')==pid:
                        m['role']='spectator'
                        try: await w.send_text(json.dumps({'type':'role_changed','role':'spectator','reason':'eliminated'},ensure_ascii=False))
                        except: pass
    if len(state['players'])==1:
        pid,rec=next(iter(state['players'].items())); state['winner']=rec['name']
    else: state['winner']='本場無冠軍'
    state['phase']='finished'; state['question']=None; state['deadline']=0
    await broadcast(public_state())

